const DECL = (over = {}) => buildDeclaration({ evaluationId: 'w', createdTs: T0 - 1, startTs: T0, durationMs: 6 * HOUR, embargoMs: HOUR, seed: 's', policyDigest: DIGEST, subject: SUBJECT, sourceRoots: SOURCES, ...over });
