  const transport = createHttpTransport({ fetchImpl: H.fetchFor(fixture), clock, log: (m) => logs.push(m) });
  const auth = createL3AuthHelper({ transport, clock, env: { K: 'key-value', S: Buffer.from('s').toString('base64') }, keyEnv: 'K', secretEnv: 'S', log: (m) => logs.push(m) });
