  const st = await stream.start(); assert.equal(st.ok, true); await H.waitFor(() => sw.latest()?.sent.some((s) => s.includes('"level3"')), { timeoutMs: 2000 }); const sock = sw.latest(); sock.deliver({ method: 'subscribe', success: true, result: { channel: 'level3', symbol: markets[0].wsname, depth: l3.depth } });
  return { stream, sock, out, logs, advance: (ms) => { t += ms; }, now: () => t, close: async () => { await stream.stop(); await fixture.close(); } };
